"""Generate audit tables from measured JSON only; conclusions written by lab lead."""
import pathlib,json
HERE=pathlib.Path(__file__).resolve().parent
s=json.loads((HERE/'summary.json').read_bytes());b=json.loads((HERE/'box-audit.json').read_bytes());lines=[]
def num(v):return 'unknown' if v is None else f'{v:.2f}'.rstrip('0').rstrip('.')
def pct(v):return 'unknown' if v is None else f'{100*v:.1f}%'
def table(title,heads,rows):
 lines.extend(['## '+title,'','| '+' | '.join(heads)+' |','| '+' | '.join(['---']*len(heads))+' |'])
 lines.extend('| '+' | '.join(str(v) for v in r)+' |' for r in rows);lines.append('')
lines.extend(['# Public-record gradient: scripted tables','',f"Frozen150-task selection; {b['attempted']} capture attempts; {b['valid_boxes']} valid Boxes; {s['common_box_tasks']} common function-target Box tasks; {s['reading_common_tasks']} common all-valid reading tasks.",'', 'Finding rows count source-verified observations, not understanding. No-timed rates use each model\'s complete records; all-six completed-task paired statistics use a smaller matched set. Endpoint edits have no first-edit time. Search lower bounds retain partial/unsupported results as unknown for upper bounds. Rank counts displayed lines, including nonmatching diagnostics; medians ordinary/Box are conditional on a visible fix result. Reading estimates are original-source body bytes, excluding formatting and later full-view overhead. No model received these Boxes.',''])
table('Matched function-target tasks: locating and search',['Model','Published solve','Tasks / complete','Timed reach median','No timed reach','Neither timed nor endpoint','Verified search / all','Opportunity lower–upper / all searches','Ordinary → Box median rank / paired move'],[[r['name'],pct(r0['published_rate']/100),str(r['box_records'])+' / '+str(r['complete_records']),num(r['median_reach_steps']),pct(r['never_recognized_rate']),pct(r['neither_timed_nor_submitted_target_rate']),str(r['measurable_search_actions'])+' / '+str(r['search_actions']),pct(r['opportunity_share_all'])+'–'+pct(r['opportunity_share_upper_all']),num(r['median_ordinary_rank'])+' → '+num(r['median_box_rank'])+' / '+num(r['median_rank_shift'])] for r,r0 in zip(s['common_table'],s['table'])])
table('All-six complete common tasks: finding sensitivity',['Model','Tasks','Timed reach median','No timed reach','No broad visibility','Neither timed nor endpoint','Restricted first10'],[[r['name'],r['complete_records'],num(r['median_reach_steps']),pct(r['never_recognized_rate']),pct(r['broad_never_visible_rate']),pct(r['neither_timed_nor_submitted_target_rate']),num(r['restricted_10_steps'])] for r in s['all_submitted_table']])
table('Paired weak minus strong: whole-task project-stratified bootstrap',['Measure','Tasks','Difference','95% interval'],[[f,v['tasks'] if v else 0,num(v['difference']) if v else 'unknown',str([round(x,4) for x in v['interval']]) if v else 'unknown'] for f,v in s['gradient'].items()])
table('After timed finding, before localized edit or censored end',['Model','Returned bytes median','Inside source bytes median','Outside source bytes median','Inside / outside unique functions median','Censored runs'],[[r['name'],num(r['after_finding_bytes_median']),num(r['after_source_bytes_inside_median']),num(r['after_source_bytes_outside_median']),num(r['after_inside_functions_median'])+' / '+num(r['after_outside_functions_median']),r['after_finding_censored']] for r in s['common_table']])
table('Body-only slicing: every common valid-Box task, including module/class gold',['Model','Valid tasks','Removable / all returned median','Removable / verified source median','Gold omission runs','Observed-edit omission runs','Repeated outside-view runs'],[[r['name'],r['slice_box_records'],pct(r['slice_removable_all_returned_share_median']),pct(r['slice_removable_view_source_share_median']),r['slice_gold_omission_runs'],r['slice_edit_omission_runs'],r['slice_repeated_outside_runs']] for r in s['reading_all_task_table']])
lines.extend(['Repeated ordinary views are a proxy, not behaviour after slicing. Gold denotes functions used by one known historical solution, not the only possible repair. An agent can need unedited reference code. Zero observed omission never proves a slice harmless.',''])
for repo,rs in s['projects'].items():
 table(repo,['Model folder','Function tasks / Box','Timed median','No timed','Neither timed nor endpoint','Search opportunity lower','Slicing tasks / median all-returned removal'],[[r['agent'],str(r['records'])+' / '+str(r['box_records']),num(r['median_reach_steps']),pct(r['never_recognized_rate']),pct(r['neither_timed_nor_submitted_target_rate']),pct(r['opportunity_share_all']),str(r['slice_box_records'])+' / '+pct(r['slice_removable_all_returned_share_median'])] for r in rs])
lines.extend(['## Hardness (secondary)','',f"All-six verdict tasks: {s['hardness_all_six_tasks']}. The available-five split is descriptive and uses the selected agents\' own outcomes; ties can cross rank-balanced quartiles. It is not an independent difficulty scale.",''])
for group,rs in s['secondary_available_five_hardness'].items():
 table('Available-five hardness group '+group+' (0 hardest)',['Model','Function tasks','Timed median','No timed','Pre-reach verified opportunity','Removable all-returned median'],[[r['name'],r['records'],num(r['median_reach_steps']),pct(r['never_recognized_rate']),pct(r['pre_reach_opportunity_rate']),pct(r['slice_removable_all_returned_share_median'])] for r in rs])
lines.extend(['## Reproduction and retained unknowns','', 'Exact manifest and source/trajectory hashes are in selection.json, record-receipts.json and box-audit.json. Full measurements retain each search action and its actual recorded locations, order and unknown flag. summary.json includes held-out, first10, same-Qwen-prompt, all-completed and per-project sensitivities. No query was rerun and no unreturned match was credited.','', 'Source status: '+str(s['statuses']), 'Unsupported searches: '+str(s['search_unknown_reasons']), 'Function-target exclusion reasons: '+str(s['function_target_reasons']), f"No base-function-region gradient excluded rows: {s['function_target_excluded_rows']}; incomplete/ambiguous measured rows: {s['incomplete_or_ambiguous_rows']}.", ''])
(HERE/'tables.md').write_bytes(('\n'.join(lines)).encode())
print('Scripted tables written')
